body.script:
//
(function () {
"use strict";

var BASE      = "https://meteorshower.space/";
var SRC       = BASE;
var CACHE_KEY = "meteorshower_space_html_cache_v1";

var boot = document.getElementById("boot");
var msg  = document.getElementById("bootMsg");
var app  = document.getElementById("app");

function inject(html) {
    if (!/<base\b/i.test(html)) {
        if (/<head([^>]*)>/i.test(html)) {
            html = html.replace(/<head([^>]*)>/i, '<head$1><base href="' + BASE + '">');
        } else {
            html = '<base href="' + BASE + '">' + html;
        }
    }

    app.srcdoc = html;
    app.classList.add("ready");
    boot.classList.add("gone");
    document.title = "BYOD";
}

function directFallback() {
    app.removeAttribute("srcdoc");
    var showed = false;
    app.onload = function () {
        showed = true;
        app.classList.add("ready");
        boot.classList.add("gone");
    };
    app.src = SRC;
    setTimeout(function () {
        if (!showed) fail("The site did not respond. The server may be stopped.");
    }, 8000);
}

function fail(reason) {
    boot.classList.remove("gone");
    app.classList.remove("ready");
    boot.innerHTML =
        '<div class="err">Couldn\'t load BYOD.<br/><span style="color:#9aa4b5;font-size:13px">' + reason + '</span></div>' +
        '<button class="retry" onclick="location.reload()">Try again</button>';
}

function fetchFresh(onSuccess, onFail) {
    fetch(SRC, { cache: "no-store", credentials: "omit" })
        .then(function (r) {
            if (!r.ok) throw new Error("Server returned " + r.status);
            return r.text();
        })
        .then(function (html) {
            if (!html || html.length < 50) throw new Error("Response looked empty.");
            try { localStorage.setItem(CACHE_KEY, html); } catch (e) {}
            onSuccess(html);
        })
        .catch(onFail);
}

function load() {
    var cached;
    try { cached = localStorage.getItem(CACHE_KEY); } catch (e) {}

    if (cached && cached.length > 50) {
        inject(cached);
        fetchFresh(function (html) {
            if (html !== cached) {
                try { localStorage.setItem(CACHE_KEY, html); } catch (e) {}
            }
        }, function () {});
    } else {
        setTimeout(function () {
            if (!app.classList.contains("ready")) msg.textContent = "Still loading…";
        }, 4000);

        directFallback();
    }
}

load();

})();//
